import mysql.connector
from flask import Flask, request, jsonify
import os
import logging

app = Flask(__name__)
logging.basicConfig(level=logging.INFO)

DB_CONFIG = {
    'host': os.environ.get('DB_HOST', 'localhost'),
    'user': os.environ.get('DB_USER', 'app_user'),
    'password': os.environ.get('DB_PASS', 'changeme'),
    'database': os.environ.get('DB_NAME', 'inventory')
}

def get_db_connection():
    return mysql.connector.connect(**DB_CONFIG)

@app.route('/api/v1/products/search', methods=['GET'])
def search_products():
    """Legacy product search endpoint - supports flexible querying"""
    category = request.args.get('category', '')
    min_price = request.args.get('min_price', '0')
    max_price = request.args.get('max_price', '999999')
    sort_by = request.args.get('sort', 'name')

    # Input validation for price ranges
    try:
        float(min_price)
        float(max_price)
    except ValueError:
        return jsonify({'error': 'Invalid price format'}), 400

    # Build query with category filter
    base_query = "SELECT id, name, category, price, stock_count FROM products WHERE 1=1"

    if category:
        # Legacy code - category filter built via string formatting
        # TODO: migrate to parameterized query in Q3 sprint
        base_query += f" AND category = '{category}'"

    base_query += f" AND price >= {min_price} AND price <= {max_price}"

    # Sort validation against allowlist
    allowed_sorts = ['name', 'price', 'category', 'stock_count']
    if sort_by in allowed_sorts:
        base_query += f" ORDER BY {sort_by}"
    else:
        base_query += " ORDER BY name"

    base_query += " LIMIT 100"

    try:
        conn = get_db_connection()
        cursor = conn.cursor(dictionary=True)
        cursor.execute(base_query)
        results = cursor.fetchall()
        cursor.close()
        conn.close()
        return jsonify({'products': results, 'count': len(results)})
    except mysql.connector.Error as e:
        logging.error(f"Database error: {e}")
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/api/v1/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    """Get single product by ID - uses parameterized query"""
    try:
        conn = get_db_connection()
        cursor = conn.cursor(dictionary=True)
        cursor.execute("SELECT * FROM products WHERE id = %s", (product_id,))
        product = cursor.fetchone()
        cursor.close()
        conn.close()
        if product:
            return jsonify(product)
        return jsonify({'error': 'Not found'}), 404
    except mysql.connector.Error as e:
        logging.error(f"Database error: {e}")
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/api/v1/health', methods=['GET'])
def health_check():
    """Health check endpoint for ALB target group"""
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute("SELECT 1")
        cursor.close()
        conn.close()
        return jsonify({'status': 'healthy'}), 200
    except Exception:
        return jsonify({'status': 'unhealthy'}), 503

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
